/**
 * Uploads a pre-built plugin binary together with its manifest.
The daemon validates the manifest, optionally verifies the
artifact signature against tenant plugin-signers, and stores
the artifact under the tenant's plugin staging directory.

Native-arch artifacts are written with `build_state=ready`.
Cross-arch / pending-build flows return `pending-build` and
delegate to the build-service (issue #142).

Cosign verification is enforced when the request includes a
non-empty `Signer-Fingerprint` header that resolves to a
`verified` signer in the tenant scope.

 * @summary Sideload a built plugin artifact
 */
export type sideloadPluginResponse = {
  data: SideloadPlugin201 | Problem | void;
  status: number;
  headers: Headers;
};

export const getSideloadPluginUrl = (tenant: string) => {
  return `/api/v1/t/${tenant}/plugins/sideload`;
};

export const sideloadPlugin = async (
  tenant: string,
  sideloadPluginBody: SideloadPluginBody,
  options?: RequestInit,
): Promise<sideloadPluginResponse> => {
  const formData = new FormData();
  formData.append('archive', sideloadPluginBody.archive);
  formData.append('manifest', sideloadPluginBody.manifest);
  if (sideloadPluginBody.signature !== undefined) {
    formData.append('signature', sideloadPluginBody.signature);
  }

  return customFetch<sideloadPluginResponse>(getSideloadPluginUrl(tenant), {
    ...options,
    method: 'POST',
    body: formData,
  });
};

